I think you are looking for something like this, which will return a list of all the words in your string that start with 't' or 'T'.  It uses regular expressions to match any word starting with either 't' or 'T', then returns only those matches.
import re

def get_words(string):
    return [word for word in re.findall('[^\W_]+', string) if word.startswith('t')]
